mapper.select:
SELECT r.*, u.nick_name AS authorName, u.avatar AS authorAvatar, COALESCE(f.cnt, 0) AS favoriteCount
FROM recipe r
JOIN user u ON r.author_id = u.user_id
LEFT JOIN (
    SELECT recipe_id, COUNT(*) AS cnt FROM favorite GROUP BY recipe_id
) f ON r.recipe_id = f.recipe_id
WHERE r.author_id IN (
    SELECT followee_id FROM follow WHERE follower_id = #{id}
)
ORDER BY r.create_time DESC

SELECT r.*, COALESCE(f.cnt, 0) AS favoriteCount
FROM recipe r
LEFT JOIN (
    SELECT recipe_id, COUNT(*) AS cnt FROM favorite GROUP BY recipe_id
) f ON r.recipe_id = f.recipe_id
WHERE r.author_id = #{id}
